// Local, project-only rule — not worth publishing as a separate package.
// Enforces the "presentation layer is always Client Components" policy
// documented in CLAUDE.md. See require-use-client.test.mjs for coverage.
export const requireUseClient = {
    meta: {
        type: "problem",
        fixable: "code",
        schema: [],
        messages: {
            missing: "Presentation components under src/components must start with 'use client';",
        },
    },
    create(context) {
        return {
            Program(node) {
                const first = node.body[0];
                // `directive` is set by the parser on directive-prologue
                // ExpressionStatements per the ESTree spec, regardless of
                // quote style. Fall back to inspecting the literal directly
                // for parsers that don't populate it, tolerating both
                // `Literal` (espree/typescript-eslint) and `StringLiteral`
                // (e.g. Babel-based parsers) node types.
                const hasDirective = first?.type === "ExpressionStatement" && (
                    first.directive === "use client" ||
                    (["Literal", "StringLiteral"].includes(first.expression.type) &&
                        first.expression.value === "use client")
                );

                if (!hasDirective) {
                    context.report({
                        node,
                        messageId: "missing",
                        // Insert before the first statement, not the Program
                        // node itself — Program's range includes any leading
                        // comments/shebang, and inserting there would place
                        // the directive ahead of those instead of after them.
                        fix: (fixer) => fixer.insertTextBefore(first ?? node, "'use client';\n\n"),
                    });
                }
            },
        };
    },
};

import assert from "node:assert/strict";

import { RuleTester } from "eslint";

import { requireUseClient } from "./require-use-client.mjs";

const ruleTester = new RuleTester({
    languageOptions: {
        ecmaVersion: "latest",
        sourceType: "module",
        parserOptions: { ecmaFeatures: { jsx: true } },
    },
});

ruleTester.run("require-use-client", requireUseClient, {
    valid: [
        "'use client';\n\nexport const Foo = () => null;",
        '"use client";\n\nexport const Foo = () => null;',
        "'use client';\n",
    ],
    invalid: [
        {
            code: "export const Foo = () => null;",
            output: "'use client';\n\nexport const Foo = () => null;",
            errors: [{ messageId: "missing" }],
        },
        {
            // A leading comment (e.g. a copyright header) must stay above the
            // inserted directive, not be pushed below it.
            code: "// Copyright header\nexport const Foo = () => null;",
            output: "// Copyright header\n'use client';\n\nexport const Foo = () => null;",
            errors: [{ messageId: "missing" }],
        },
        {
            // A different directive (e.g. 'use server') doesn't satisfy this
            // rule — 'use client' must still be added.
            code: "'use server';\n\nexport const Foo = () => null;",
            output: "'use client';\n\n'use server';\n\nexport const Foo = () => null;",
            errors: [{ messageId: "missing" }],
        },
        {
            // No statements at all — falls back to inserting before Program.
            code: "// just a comment\n",
            output: "// just a comment\n'use client';\n\n",
            errors: [{ messageId: "missing" }],
        },
    ],
});

// Babel-based parsers represent string literals as `StringLiteral` rather
// than espree's `Literal`, so this branch can't be exercised via RuleTester
// (which parses with espree here) without adding a Babel parser dependency
// just for this. Exercise it directly against a synthetic node instead.
{
    let reported = false;
    const listeners = requireUseClient.create({ report: () => { reported = true; } });

    listeners.Program({
        body: [{
            type: "ExpressionStatement",
            expression: { type: "StringLiteral", value: "use client" },
        }],
    });

    assert.equal(reported, false, "a StringLiteral 'use client' directive should be recognised");
}

console.log("require-use-client: all rule tests passed");

